/**
 * GENERATED FILE PRODUCER — writes lib/geometry/__fixtures__/phase16-fin-pin.json: every fin of the 32 Phase 16 fin
 * cases (`phase16FinCases`, lib/geometry/__fixtures__/phase16-fin-cases.ts) as plan 16-10 left them, one plain
 * outline per role, BEFORE each fin took a real shape for its setup (D-35, plan 16-17). The output is generated and
 * must never be hand-edited.
 *
 *   npx --no-install tsx --tsconfig ./tsconfig.json scripts/extract-phase16-fin-pin.ts
 *
 * run from the repository root. It is a record of the code as it stood, so it REFUSES to run once
 * `lib/geometry/fin-outline.ts` exports `FIN_TEMPLATES`: from then on the fins it would write are the new ones, and
 * the pin would prove nothing. It ran exactly once. (Nothing in package.json — `--no-install` means npx can only run
 * the tsx already in node_modules. No database is involved.)
 *
 * Each fin is `<preset id>|<case>|<mark index>`, its figures plain JSON numbers, which JSON keeps exactly.
 */
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";
import { finMeasures, phase16FinCases } from "@/lib/geometry/__fixtures__/phase16-fin-cases";
import * as finOutline from "@/lib/geometry/fin-outline";
import { placedFins } from "@/lib/geometry/fin-outline";

const OUTPUT = path.resolve(process.cwd(), "lib/geometry/__fixtures__/phase16-fin-pin.json");

function main() {
  if (!existsSync(path.resolve(process.cwd(), "lib/geometry/fin-outline.ts"))) {
    throw new Error("Run this from the repository root (lib/geometry/fin-outline.ts not found here).");
  }
  if ("FIN_TEMPLATES" in finOutline) {
    throw new Error("the pin records 16-10's fins from before D-35 — it is never re-run");
  }
  const fins: Record<string, unknown> = {};
  for (const { label, preset, spec, marks, rockerAt } of phase16FinCases()) {
    const placed = placedFins(marks, spec.finSetup, spec.twinTemplate, preset.outline.length, rockerAt);
    if (placed.length !== marks.length) throw new Error(`${label}: a fin was left out`);
    placed.forEach((fin, i) => {
      fins[`${label}|${i}`] = {
        markRole: marks[i].role,
        side: marks[i].side,
        role: fin.role,
        base: fin.outline.base,
        depth: fin.outline.depth,
        thickness: fin.thickness,
        leading: fin.leading,
        trailing: fin.trailing,
        rootZ: fin.rootZ,
        tiltRad: fin.tiltRad,
        points: fin.outline.points.length,
        ...finMeasures(fin.outline),
      };
    });
  }
  const provenance = "GENERATED by scripts/extract-phase16-fin-pin.ts from 16-10's fins, before D-35 — never re-run";
  writeFileSync(OUTPUT, `${JSON.stringify({ provenance, fins }, null, 2)}\n`);
  console.log(`wrote ${path.relative(process.cwd(), OUTPUT)} (${Object.keys(fins).length} fins)`);
}

try {
  main();
} catch (error: unknown) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}
